#include <stdio.h>
#include <string.h>
#include <limits.h>

#define MAX_H 50
#define MAX_W 50

int h, w;
char grid[MAX_H][MAX_W+1];
int dist[MAX_H][MAX_W][2]; // 0 = on ground, 1 = in moat

typedef struct {
    int r, c, in_moat;
} State;

int bfs(int sr, int sc, int tr, int tc) {
    State q[MAX_H * MAX_W * 2];
    int front = 0, back = 0;
    for (int i = 0; i < h; i++)
        for (int j = 0; j < w; j++)
            dist[i][j][0] = dist[i][j][1] = INT_MAX;

    int start_in_moat = (grid[sr][sc] == '#');
    dist[sr][sc][start_in_moat] = 0;
    q[back++] = (State){sr, sc, start_in_moat};

    int dr[] = {1, -1, 0, 0};
    int dc[] = {0, 0, 1, -1};

    while (front < back) {
        State cur = q[front++];
        int r = cur.r, c = cur.c, m = cur.in_moat;
        int d = dist[r][c][m];

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr < 0 || nr >= h || nc < 0 || nc >= w) continue;

            int nm = (grid[nr][nc] == '#') ? 1 : 0;
            int nd = d;
            if (m == 1 && nm == 0) nd = d + 1; // climbing out

            if (nd < dist[nr][nc][nm]) {
                dist[nr][nc][nm] = nd;
                q[back++] = (State){nr, nc, nm};
            }
        }
    }

    int ans = INT_MAX;
    for (int m = 0; m < 2; m++)
        if (dist[tr][tc][m] < ans)
            ans = dist[tr][tc][m];
    return ans;
}

int main() {
    while (1) {
        scanf("%d %d", &h, &w);
        if (h == 0 && w == 0) break;

        int sr, sc, tr, tc;
