            scanf("%s", grid[i]);
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '&') {
                    tr = i; tc = j;
                    grid[i][j] = '.'; // treat as ground
                }
            }
        }
        // ninja starts outside; we can treat first cell as start
        // The problem statement: 'outside' means we start from outside the grid.
        // So we pick any border '.' and start from there.
        // But for simplicity, we can start BFS from every border ground cell.
        // Actually, "outside" means starting cell is not given.
        // We'll treat the ninja starting from any ground '.' on the border.

        int best = INT_MAX;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '.' && (i == 0 || i == h-1 || j == 0 || j == w-1)) {
