#define MAXN 105
#define INF 1000000

int dist[MAXN][MAXN];
char grid[MAXN][MAXN];
int W, H;
int dx[] = {0,0,1,-1};
int dy[] = {1,-1,0,0};

// 0-1 BFS using deque
int dq_r[MAXN*MAXN*2], dq_c[MAXN*MAXN*2];
int head, tail;

void push_front(int r, int c) { head = (head - 1 + MAXN*MAXN*2) % (MAXN*MAXN*2); dq_r[head]=r; dq_c[head]=c; }
void push_back(int r, int c) { dq_r[tail]=r; dq_c[tail]=c; tail=(tail+1)%(MAXN*MAXN*2); }

int main() {
    while (scanf("%d %d", &W, &H) == 2 && (W||H)) {
        for (int i = 0; i < H; i++) scanf("%s", grid[i]);

        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++)
                dist[i][j] = INF;

        head = tail = 0;
        int sz = MAXN*MAXN*2;

        // Initialize: all border cells reachable from outside ('.')
        // Outside is '.', so cost to enter border cell:
        // if border cell is '#': 0 (entering moat)
        // if border cell is '.': 0 (staying on ground)
        // if border cell is '&': 0
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (i==0||i==H-1||j==0||j==W-1) {
                    // coming from outside ('.')
                    int cost = (grid[i][j] != '#') ? 0 : 0; // entering '#' is free
                    // Actually climbing out is '#'->'.' so entering from '.' to '#' = 0
                    dist[i][j] = 0;
                    push_back(i, j);
                }
            }
        }

        while (head != tail) {
            int r = dq_r[head], c = dq_c[head];
            head = (head+1)%sz;
            for (int d = 0; d < 4; d++) {
                int nr = r+dx[d], nc = c+dy[d];
                if (nr<0||nr>=H||nc<0||nc>=W) continue;
                // cost: 1 if current is '#' and next is not '#', else 0
                int cost = (grid[r][c]=='#' && grid[nr][nc]!='#') ? 1 : 0;
                if (dist[r][c]+cost < dist[nr][nc]) {
                    dist[nr][nc] = dist[r][c]+cost;
                    if (cost==0) push_front(nr,nc);
                    else push_back(nr,nc);
                }
            }
        }

        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++)
                if (grid[i][j]=='&') printf("%d\n", dist[i][j]);
    }
}

