                    dq[tail++] = (Node){j, i};
                }
            }
        }

        int dx[4] = {1, -1, 0, 0};
        int dy[4] = {0, 0, 1, -1};

        while (head < tail) {
            Node cur = dq[head++];
            int x = cur.x, y = cur.y;

            for (int k = 0; k < 4; k++) {
                int nx = x + dx[k];
