        deque<pair<int,int>> dq;

        // Start from all boundary cells: ninja comes from outside.
        for (int r = 0; r < H; ++r) {
            for (int c : {0, W - 1}) {
                if (dist[r][c] == INF) {
                    dist[r][c] = 0;
                    dq.push_front({r, c});
                }
            }
        }
        for (int c = 0; c < W; ++c) {
            for (int r : {0, H - 1}) {
                if (dist[r][c] == INF) {
                    dist[r][c] = 0;
                    dq.push_front({r, c});
                }
            }
        }

        auto inside = [&](int r, int c) {
            return 0 <= r && r < H && 0 <= c && c < W;
        };

        int dr[4] = {-1, 1, 0, 0};
        int dc[4] = {0, 0, -1, 1};

        // 0-1 BFS:
        // cost 1 when moving from '#' to non-'#' (climbing out of moat), else 0.
        while (!dq.empty()) {
            auto [r, c] = dq.front();
            dq.pop_front();

            for (int k = 0; k < 4; ++k) {
