public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static final int INF = 1 << 29;
    static final int[] DR = {-1, 1, 0, 0};
    static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            String ws = fs.next();
            if (ws == null) break;
            String hs = fs.next();
            int W = Integer.parseInt(ws);
            int H = Integer.parseInt(hs);

            if (W == 0 && H == 0) break;

            char[][] g = new char[H][W];
            int tr = -1, tc = -1;

            for (int i = 0; i < H; i++) {
                String s = fs.next();
                for (int j = 0; j < W; j++) {
                    g[i][j] = s.charAt(j);
                    if (g[i][j] == '&') {
                        tr = i;
                        tc = j;
                    }
                }
            }

            int[][] dist = new int[H][W];
            for (int i = 0; i < H; i++) Arrays.fill(dist[i], INF);

            Deque<int[]> dq = new ArrayDeque<>();

            // Start from all boundary cells: entering from outside to boundary costs 0
            // because we count only climbing OUT of the moat.
            for (int r = 0; r < H; r++) {
                for (int c = 0; c < W; c++) {
                    if (r == 0 || r == H - 1 || c == 0 || c == W - 1) {
                        if (dist[r][c] > 0) {
                            dist[r][c] = 0;
                            dq.addFirst(new int[]{r, c});
                        }
                    }
                }
            }

            while (!dq.isEmpty()) {
                int[] cur = dq.pollFirst();
                int r = cur[0], c = cur[1];
                int d = dist[r][c];

                if (r == tr && c == tc) break;

                for (int k = 0; k < 4; k++) {
                    int nr = r + DR[k];
                    int nc = c + DC[k];
                    if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;

                    // Cost is 1 exactly when moving from moat to non-moat:
                    // that means climbing out of the moat.
                    int w = (g[r][c] == '#' && g[nr][nc] != '#') ? 1 : 0;

                    if (dist[nr][nc] > d + w) {
                        dist[nr][nc] = d + w;
                        if (w == 0) dq.addFirst(new int[]{nr, nc});
                        else dq.addLast(new int[]{nr, nc});
                    }
                }
            }

            out.append(dist[tr][tc]).append('\n');
        }

        System.out.print(out.toString());
    }
}

