import sys
from collections import deque

def solve():
    it = iter(sys.stdin.read().splitlines())
    out = []

    while True:
        try:
            w = int(next(it))
            h = int(next(it))
        except StopIteration:
            break

        if w == 0 and h == 0:
            break

        grid = []
        target = None
        for i in range(h):
            row = next(it).rstrip('\n')
            grid.append(row)
            j = row.find('&')
            if j != -1:
                target = (i, j)

        # 0-1 BFS on states:
        # cost increases by 1 exactly when moving from '#' to non-'#'
        INF = 10**18
        dist = [[INF] * w for _ in range(h)]
        dq = deque()

        # Start from any border cell (outside -> border).
        # Entering the moat does not cost; climbing out does.
        for i in range(h):
            for j in (0, w - 1):
                if dist[i][j] > 0:
                    dist[i][j] = 0
                    dq.appendleft((i, j))
        for j in range(w):
            for i in (0, h - 1):
                if dist[i][j] > 0:
                    dist[i][j] = 0
                    dq.appendleft((i, j))

        dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        while dq:
            x, y = dq.popleft()
            if (x, y) == target:
                break
            cur = grid[x][y]
            d = dist[x][y]

            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < h and 0 <= ny < w:
                    nxt = grid[nx][ny]
                    wgt = 1 if cur == '#' and nxt != '#' else 0
                    nd = d + wgt
                    if nd < dist[nx][ny]:
                        dist[nx][ny] = nd
                        if wgt == 0:
                            dq.appendleft((nx, ny))
                        else:
                            dq.append((nx, ny))

        out.append(str(dist[target[0]][target[1]]))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
